referenceFixTemplate:
#include <stdio.h>

/* 招牌：这一招收三只数，还一只 */
int fish_mix(int base, int bonus, int extra);

/* 身子：照着招牌接手，收三只 */
int fish_mix(int base, int bonus, int extra) {
    return base + bonus + extra;
}

int main(void) {
    printf("混起来 %d 条\n", fish_mix({a}, {b}, {c}));
    return 0;
}
